import { useMatchingBreakpoints } from "@/core/hooks/use-matching-breakpoints";
import { useMemo } from "react";

/**
 * Custom hook that checks if the current screen size is mobile.
 * It uses the `useMatchingBreakpoints` hook to get the current breakpoints and checks if "medium" is included in the list.
 * If "medium" is not included, it means the screen size is mobile.
 * @returns {boolean} True if the screen size is mobile, false otherwise.
 * @important Make sure to update this hook if the breakpoints change
 */
export const useIsMobile = () => {
  const matchingBreakpoints = useMatchingBreakpoints();

  const isMobile = useMemo(() => {
    return !matchingBreakpoints.includes("medium");
  }, [matchingBreakpoints]);

  return isMobile;
};
