import type { Meta, StoryObj } from "@storybook/react";
import { useConfetti } from "./confetti-launcher";
import { PrimaryButton, SecondaryButton } from "@/core/components/primitives/parks-button/parks-button";

type ConfettiDirection = "center" | "bottom" | "left" | "right" | "top";

type ConfettiDemoProps = {
  launchDirections: Array<ConfettiDirection>;
  snowfallDuration: number | "continuous";
};

/**
 * Demo component to showcase the useConfetti hook functionality.
 * In real usage, you'd call these functions from your own component.
 */
const ConfettiDemo = ({ launchDirections, snowfallDuration }: ConfettiDemoProps) => {
  const { confettiLauncher, confettiSnowfall, stopConfetti } = useConfetti();

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "16px",
        padding: "24px",
        backgroundColor: "var(--foundation-color-primary-300",
        height: "100vh",
      }}
    >
      <h2 style={{ margin: 0 }}>Confetti Launcher Demo</h2>
      <p style={{ margin: 0, color: "#666" }}>
        The <code>useConfetti</code> hook provides three functions for confetti animations.
      </p>

      <div style={{ display: "flex", gap: "12px", flexWrap: "wrap" }}>
        <PrimaryButton onClick={() => confettiLauncher(launchDirections)} label="🎉 Launch Confetti" />
        <SecondaryButton onClick={() => confettiSnowfall(snowfallDuration)} label="❄️ Start Snowfall"></SecondaryButton>
        <PrimaryButton complementary onClick={() => stopConfetti()} label="🛑 Stop Confetti"></PrimaryButton>
      </div>

      <div
        style={{
          marginTop: "24px",
          padding: "16px",
          backgroundColor: "#f5f5f5",
          borderRadius: "8px",
          fontSize: "14px",
        }}
      >
        <strong>Current Settings:</strong>
        <ul style={{ margin: "8px 0 0", paddingLeft: "20px" }}>
          <li>
            Launch directions: <code>{JSON.stringify(launchDirections)}</code>
          </li>
          <li>
            Snowfall duration:{" "}
            <code>{snowfallDuration === "continuous" ? '"continuous"' : `${snowfallDuration}ms`}</code>
          </li>
        </ul>
      </div>
    </div>
  );
};

const meta: Meta<typeof ConfettiDemo> = {
  title: "Primitives/Confetti Launcher",
  component: ConfettiDemo,
  argTypes: {
    launchDirections: {
      control: { type: "check" },
      options: ["center", "top", "bottom", "left", "right"],
      description: "Directions to launch confetti from",
    },
    snowfallDuration: {
      control: { type: "select" },
      options: [5000, 10000, 15000, 30000, "continuous"],
      description: "Duration of snowfall effect (ms or continuous)",
    },
  },
  args: {
    launchDirections: ["center"],
    snowfallDuration: 15000,
  },
  parameters: {
    docs: {
      description: {
        component: `
The \`useConfetti\` hook provides confetti animation controls with automatic cleanup.

### Features
- **confettiLauncher**: Fire one-shot confetti burst(s) from specified direction(s)
- **confettiSnowfall**: Start continuous snowfall effect with mobile optimization
- **stopConfetti**: Manually stop any running confetti animations

### Usage
\`\`\`tsx
const { confettiLauncher, confettiSnowfall, stopConfetti } = useConfetti();

// Launch from multiple directions
confettiLauncher(["top", "left", "right"]);

// Start 10 second snowfall
confettiSnowfall(10000);

// Or continuous snowfall
confettiSnowfall("continuous");

// Stop early
stopConfetti();
\`\`\`
        `,
      },
    },
  },
};
export default meta;

type Story = StoryObj<typeof ConfettiDemo>;

export const Default: Story = {
  args: {
    launchDirections: ["center"],
    snowfallDuration: 15000,
  },
};

export const MultiDirection: Story = {
  args: {
    launchDirections: ["top", "left", "right"],
    snowfallDuration: 15000,
  },
};

export const AllDirections: Story = {
  args: {
    launchDirections: ["center", "top", "bottom", "left", "right"],
    snowfallDuration: 15000,
  },
};

export const ContinuousSnowfall: Story = {
  args: {
    launchDirections: ["center"],
    snowfallDuration: "continuous",
  },
};

export const QuickBurst: Story = {
  args: {
    launchDirections: ["bottom"],
    snowfallDuration: 5000,
  },
};
